defmodule Clickhousex.Result do
  @moduledoc """
  Result struct returned from any successful query. Its fields are:

    * `query_id` - A string, generated by Clickhouse, that uniquely identifies the query
    * `summary` - A map with basic stats about read/written bytes and rows
    * `command` - An atom of the query command
    * `columns` - The column names;
    * `rows` - The result set. A list of lists, each inner list corresponding to a
               row, each element in the inner list corresponds to a column;
    * `num_rows` - The number of fetched or affected rows;
  """

  @type t :: %__MODULE__{
          query_id: String.t() | nil,
          summary: Map.t() | nil,
          command: atom,
          columns: [String.t()] | nil,
          column_types: [String.t()] | nil,
          rows: [[term] | binary] | nil,
          num_rows: integer | :undefined
        }

  defstruct query_id: nil, summary: nil, command: nil, columns: nil, column_types: nil, rows: nil, num_rows: :undefined
end
